'select h.occupation_code as "c001",',
'       json_value(',
'         h.result_payload,',
'         ''$.title''',
'         returning varchar2(4000)',
'         null on error',
'       ) as "c002",',
'       (',
unistr('         select listagg(''\2022 '' || item_text, chr(10))'),
'                  within group (order by ordinal)',
'           from json_table(',
'             h.result_payload,',
'             ''$.good_fit[*]''',
'             columns (',
'               ordinal for ordinality,',
'               item_text varchar2(4000) path ''$''',
'             )',
'           )',
'       ) as "c003",',
'       (',
unistr('         select listagg(''\2022 '' || item_text, chr(10))'),
'                  within group (order by ordinal)',
'           from json_table(',
'             h.result_payload,',
'             ''$.needs_improvement[*]''',
'             columns (',
'               ordinal for ordinality,',
'               item_text varchar2(4000) path ''$''',
'             )',
'           )',
'       ) as "c004",',
'       (',
unistr('         select listagg(''\2022 '' || item_text, chr(10))'),
'                  within group (order by ordinal)',
'           from json_table(',
'             h.result_payload,',
'             ''$.suggestions[*]''',
'             columns (',
'               ordinal for ordinality,',
'               item_text varchar2(4000) path ''$''',
'             )',
'           )',
'       ) as "c005"',
'  from career_profile_task_history h',
' where h.conversation_id = :P2_CONVERSATION_ID',
'   and h.task_order = 4',
'   and h.status = ''SUCCEEDED''',
'union all',
'select ''ERROR'' as "c001",',
'       json_value(',
'         h.result_payload,',
'         ''$.message''',
'         returning varchar2(4000)',
'         null on error',
'       ) as "c002",',
'       null as "c003",',
'       null as "c004",',
'       null as "c005"',
'  from career_profile_task_history h',
' where h.conversation_id = :P2_CONVERSATION_ID',
'   and h.task_order = 4',
'   and h.status = ''ERROR''',
' order by 2'))
