wwv_flow_imp_page.create_report_region(
 p_id=>wwv_flow_imp.id(14203602107003923)
,p_name=>'Career Exploration Results'
,p_static_id=>'task-three-recommendations'
,p_template=>4073835273271169698
,p_display_sequence=>30
,p_region_template_options=>'#DEFAULT#'
,p_component_template_options=>'#DEFAULT#:t-Report--stretch:t-Report--horizontalBorders'
,p_source_type=>'NATIVE_SQL_REPORT'
,p_query_type=>'SQL'
,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'with latest_task as (',
'    select h.result_payload,',
'           json_value(h.result_payload, ''$.status'') as result_status,',
'           json_value(h.result_payload, ''$.message'') as result_message,',
'           coalesce(',
'             json_query(h.result_payload, ''$.result.occupations'' returning clob),',
'             json_query(h.result_payload, ''$.occupations'' returning clob),',
'             json_query(',
'               json_value(',
'                 h.result_payload,',
'                 ''$.result'' returning clob null on error',
'               ),',
'               ''$.result.occupations'' returning clob',
'             ),',
'             json_query(',
'               json_value(',
'                 h.result_payload,',
'                 ''$.result'' returning clob null on error',
'               ),',
'               ''$.occupations'' returning clob',
'             )',
'           ) as occupations',
'      from career_profile_task_history h',
'     where h.conversation_id = :P2_CONVERSATION_ID',
'       and h.task_order = 3',
'     order by h.history_id desc',
'     fetch first 1 row only',
')',
'select jt.onetsoc_code as "c001",',
'       jt.occupation_title as "c002"',
'  from latest_task h,',
'       json_table(',
'         h.occupations,',
'         ''$[*]''',
'         columns (',
'           onetsoc_code varchar2(20) path ''$.onetsoc_code'',',
'           occupation_title varchar2(4000) path ''$.title''',
'         )',
'       ) jt',
' where lower(coalesce(h.result_status, ''success'')) <> ''error''',
'union all',
'select ''ERROR'',',
'       substr(coalesce(result_message, ''Task 3 did not return career results''), 1, 4000)',
'  from latest_task',
' where lower(result_status) = ''error''',
'union all',
'select ''INFO'', ''No career matches were returned.''',
'  from latest_task',
' where lower(coalesce(result_status, ''success'')) <> ''error''',
'   and json_query(occupations, ''$[0]'' returning clob) is null',
' order by 2'))
,p_ajax_enabled=>'Y'
,p_ajax_items_to_submit=>'P2_CONVERSATION_ID'
,p_lazy_loading=>false
,p_query_row_template=>2540130677583398057
,p_query_num_rows=>15
,p_query_options=>'DERIVED_REPORT_COLUMNS'
,p_csv_output=>'N'
,p_prn_output=>'N'
,p_sort_null=>'L'
,p_plug_query_strip_html=>'N'
);
