wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(18800123460283501)
,p_plug_name=>'Visualization Result'
,p_static_id=>'visualization-result'
,p_region_template_options=>'#DEFAULT#:js-showMaximizeButton:t-Region--scrollBody'
,p_plug_template=>4073835273271169698
,p_plug_display_sequence=>40
,p_plug_item_display_point=>'ABOVE'
,p_query_type=>'FUNC_BODY_RETURNING_SQL'
,p_function_body_language=>'PLSQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    l_sql CLOB;',
'    l_status VARCHAR2(30);',
'BEGIN',
'    SELECT JSON_VALUE(h.result_payload, ''$.sql'' RETURNING CLOB),',
'           JSON_VALUE(h.result_payload, ''$.status'' RETURNING VARCHAR2(30))',
'      INTO l_sql, l_status',
'      FROM career_profile_task_history h',
'     WHERE h.conversation_id = :P2_CONVERSATION_ID',
'       AND h.task_order = 3',
'     ORDER BY h.history_id DESC',
'     FETCH FIRST 1 ROW ONLY;',
'',
'    IF l_status = ''error'' THEN',
'        l_sql := NULL;',
'    END IF;',
'',
'    IF l_sql IS NOT NULL THEN',
'        -- Return Task 3''s stored graph query unchanged. The',
'        -- visualization plug-in re-executes this statement for',
'        -- each page and supplies only page_start/page_size.',
'        RETURN l_sql;',
'    END IF;',
'',
'    RETURN q''~select',
'                  cast(null as varchar2(4000)) as v1_id,',
'                  cast(null as varchar2(4000)) as occupation_code,',
'                  cast(null as varchar2(4000)) as e_id,',
'                  cast(null as varchar2(4000)) as v2_id,',
'                  cast(null as varchar2(4000)) as element_id,',
'                  cast(null as number) as distance',
'             from dual',
'            where 1 = 0~'';',
'EXCEPTION',
'    WHEN NO_DATA_FOUND THEN',
'        RETURN q''~select',
'                  cast(null as varchar2(4000)) as v1_id,',
'                  cast(null as varchar2(4000)) as occupation_code,',
'                  cast(null as varchar2(4000)) as e_id,',
'                  cast(null as varchar2(4000)) as v2_id,',
'                  cast(null as varchar2(4000)) as element_id,',
'                  cast(null as number) as distance',
'             from dual',
'            where 1 = 0~'';',
'END;'))
,p_plug_source_type=>'PLUGIN_GRAPHVIZ'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
