,p_action=>'NATIVE_JAVASCRIPT_CODE'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'js_code', wwv_flow_string.join(wwv_flow_t_varchar2(
    '(function () {',
    '  var region = $(".t-Region").filter(function () {',
    '    return $.trim(',
    '      $(this).find(".t-Region-title").first().text()',
    '    ) === "Career Fit Details";',
    '  }).first();',
    '  var regionId = region.attr("id");',
    '  var regionApi = regionId ? apex.region(regionId) : null;',
    '  var body = region.find(".t-Region-body").first();',
    '',
    '  body.removeAttr("aria-busy");',
    '  body.find(".career-fit-loading").remove();',
    '  body.children().show();',
    '  if (regionApi && regionApi.refresh) {',
    '    regionApi.refresh();',
    '  }',
    '  region.show();',
    '}());')))).to_clob
);
wwv_flow_imp_page.create_page_da_action(
 p_id=>wwv_flow_imp.id(29600660725878015)
,p_event_id=>wwv_flow_imp.id(15004294676088047)
,p_event_result=>'TRUE'
,p_action_sequence=>20
,p_execute_on_page_init=>'N'
,p_static_id=>'refresh-profile-results'
,p_action=>'NATIVE_JAVASCRIPT_CODE'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'js_code', wwv_flow_string.join(wwv_flow_t_varchar2(
    '(function () {',
    '  var attempts = 0;',
    '',
    '  function waitForCareerResults() {',
    '    var conversationId = apex.item("P2_CONVERSATION_ID").getValue();',
    '',
    '    if (!conversationId && attempts < 120) {',
    '      attempts += 1;',
    '      window.setTimeout(waitForCareerResults, 250);',
    '      return;',
    '    }',
    '',
    '    if (!conversationId) {',
    '      return;',
    '    }',
    '',
    '    function refreshRegionByTitle(title) {',
    '      var region = $(".t-Region").filter(function () {',
    '        return $.trim($(this).find(".t-Region-title").first().text()) === title;',
    '      }).first();',
    '      var regionId = region.attr("id");',
    '      var regionApi = regionId ? apex.region(regionId) : null;',
    '      var body = region.find(".t-Region-body").first();',
    '',
    '      body.removeAttr("aria-busy");',
    '      body.find(',
    '        ".career-exploration-loading," +',
    '        ".career-visualization-loading"',
    '      ).remove();',
    '      body.children().show();',
    '',
    '      if (regionApi && regionApi.refresh) {',
    '        regionApi.refresh();',
    '      }',
    '      region.show();',
    '    }',
    '',
    '    refreshRegionByTitle("Career Exploration Results");',
    '    refreshRegionByTitle("Visualization Result");',
    '  }',
    '',
    '  waitForCareerResults();',
    '}());')))).to_clob
);
wwv_flow_imp_page.create_page_da_action(
 p_id=>wwv_flow_imp.id(44600241070997499)
,p_event_id=>wwv_flow_imp.id(15004294676088047)
,p_event_result=>'TRUE'
,p_action_sequence=>3
,p_execute_on_page_init=>'N'
,p_static_id=>'show-results-loading'
,p_action=>'NATIVE_JAVASCRIPT_CODE'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'js_code', wwv_flow_string.join(wwv_flow_t_varchar2(
    '(function () {',
    '  function showLoading(title, message, loadingClass) {',
    '    var region = $(".t-Region").filter(function () {',
    '      return $.trim(',
    '        $(this).find(".t-Region-title").first().text()',
    '      ) === title;',
    '    }).first();',
    '    var body = region.find(".t-Region-body").first();',
    '',
    '    if (!region.length || !body.length) {',
    '      return;',
    '    }',
    '',
    '    body.find("." + loadingClass).remove();',
    '    body.children().hide();',
    '    body.attr("aria-busy", "true");',
    '    body.prepend(',
    '      ''<div class="'' + loadingClass +',
    '      '' u-flex u-align-items-center u-justify-content-center" '' +',
    '      ''style="min-height:8rem;gap:.75rem">'' +',
    '      ''<span class="fa fa-refresh fa-anim-spin" '' +',
    '      ''aria-hidden="true"></span>'' +',
    '      ''<span>'' + message + ''</span>'' +',
    '      ''</div>''',
    '    );',
    '    region.show();',
    '  }',
    '',
    '  showLoading(',
    '    "Career Exploration Results",',
    '    "Exploring career options&hellip;",',
    '    "career-exploration-loading"',
    '  );',
    '  showLoading(',
    '    "Visualization Result",',
    '    "Building career visualization&hellip;",',
    '    "career-visualization-loading"',
    '  );',
    '  showLoading(',
    '    "Career Fit Details",',
    '    "Analyzing career fit&hellip;",',
    '    "career-fit-loading"',
    '  );',
    '}());')))).to_clob
);
